Solution A: ```javascript
function createVoiceControlledRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    canvas.width = width;
    canvas.height = height;

    let carX = width / 2;
    let carY = height - 50;
    let carSpeed = 0;
    let carAngle = 0;
    let lapTime = 0;
    let bestLapTime = Infinity;
    let raceStarted = false;
    let raceCompleted = false;
    let audioContext,    let analyser,    let microphone,    let mute = false;

    function drawCar() {
        ctx.save();
        ctx.translate(carX, carY);
        ctx.rotate(carAngle);
        ctx.fillStyle = 'red';
        ctx.fillRect(-25, -25, 50, 50);
        ctx.restore();
    }

    function drawTrack() {
        ctx.fillStyle = 'green';
        ctx.fillRect(0, 0, width, height);
    }

    function drawVolumeMeter(volume) {
        ctx.fillStyle = 'blue';
        ctx.fillRect(width - 20, 10, 10, volume * (height - 20));
    }

    function startRace() {
        if (!raceStarted && !raceCompleted) {
            raceStarted = true;
            lapTime = Date.now();
        }
    }

    function completeRace() {
        if (raceStarted && !raceCompleted) {
            raceCompleted = true;
            const currentTime = Date.now();
            const lapDuration = (currentTime - lapTime) / 1000;
            if (lapDuration < bestLapTime) {
                bestLapTime = lapDuration;
            }
            alert(`Race Completed! Lap Time: ${lapDuration.toFixed(2)}s, Best Lap: ${bestLapTime.toFixed(2)}s`);
        }
    }

    function checkCrash() {
        // Simple crash detection logic
        if (carX < 0 || carX > width || carY < 0 || carY > height) {
            alert('Crashed!');
            raceCompleted = true;
        }
    }

    function updateCarPosition() {
        carX += carSpeed * Math.cos(carAngle);
        carY += carSpeed * Math.sin(carAngle);
        checkCrash();
    }

    function handleMicrophoneInput() {
        if (audioContext && microphone) {
            const bufferLength = analyser.frequencyBinCount;
            const dataArray = new Float32Array(bufferLength);
            analyser.getByteFrequencyData(dataArray);

            let sum = 0;
            for (let i = 0; i < bufferLength; i++) {
                sum += dataArray[i];
            }
            const average = sum / bufferLength;
            carSpeed = average / 255 * 5; // Scale speed based on volume
        }
    }

    function toggleMute() {
        mute = !mute;
        if (microphone) {
            microphone.muted = mute;
        }
    }

    function setupAudio() {
        try {
            audioContext = new (window.AudioContext || window.webkitAudioContext)();
            analyser = audioContext.createAnalyser();
            microphone = audioContext.createMediaStreamSource(navigator.mediaDevices.getUserMedia({ audio: true }));
            microphone.connect(analyser);
            analyser.fftSize = 2048;
        } catch (err) {
            console.error('Error accessing microphone:', err);
            alert('Could not access microphone. Please allow permission.');
        }
    }

    function gameLoop() {
        if (!raceCompleted) {
            ctx.clearRect(0, 0, width, height);
            drawTrack();
            drawCar();
            drawVolumeMeter(carSpeed);
            updateCarPosition();
            requestAnimationFrame(gameLoop);
        }
    }

    function createStartButton() {
        const button = document.createElement('button');
        button.textContent = 'Start Race';
        button.addEventListener('click', startRace);
        document.body.appendChild(button);
    }

    function createMuteToggle() {
        const toggle = document.createElement('button');
        toggle.textContent = 'Mute/Unmute';
        toggle.addEventListener('click', toggleMute);
        document.body.appendChild(toggle);
    }

    setupAudio();
    createStartButton();
    createMuteToggle();
    gameLoop();
}
```

Solution B: function createVoiceRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // UI Elements
    const container = document.createElement('div');
    container.style.position = 'relative';
    canvas.parentNode.insertBefore(container, canvas);
    container.appendChild(canvas);

    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Race';
    startBtn.style.position = 'absolute';
    startBtn.style.top = '10px';
    startBtn.style.left = '10px';
    container.appendChild(startBtn);

    const muteBtn = document.createElement('button');
    muteBtn.textContent = 'Mute';
    muteBtn.style.position = 'absolute';
    muteBtn.style.top = '10px';
    muteBtn.style.left = '100px';
    container.appendChild(muteBtn);

    const timerDiv = document.createElement('div');
    timerDiv.style.position = 'absolute';
    timerDiv.style.top = '10px';
    timerDiv.style.right = '10px';
    timerDiv.style.color = '#fff';
    timerDiv.style.font = '16px monospace';
    container.appendChild(timerDiv);

    const bestDiv = document.createElement('div');
    bestDiv.style.position = 'absolute';
    bestDiv.style.top = '30px';
    bestDiv.style.right = '10px';
    bestDiv.style.color = '#fff';
    bestDiv.style.font = '14px monospace';
    container.appendChild(bestDiv);

    const meterCanvas = document.createElement('canvas');
    meterCanvas.width = 200;
    meterCanvas.height = 20;
    meterCanvas.style.position = 'absolute';
    meterCanvas.style.bottom = '10px';
    meterCanvas.style.left = '50%';
    meterCanvas.style.transform = 'translateX(-50%)';
    container.appendChild(meterCanvas);
    const meterCtx = meterCanvas.getContext('2d');

    // Audio Setup
    let audioCtx, analyser, sourceNode, gainNode;
    let volume = 0;
    let muted = false;
    let micReady = false;

    navigator.mediaDevices.getUserMedia({ audio: true })
        .then(stream => {
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            analyser = audioCtx.createAnalyser();
            analyser.fftSize = 512;
            sourceNode = audioCtx.createMediaStreamSource(stream);
            gainNode = audioCtx.createGain();
            sourceNode.connect(gainNode).connect(analyser);
            micReady = true;
            startBtn.disabled = false;
        })
        .catch(() => {
            alert('Microphone permission denied. Game cannot start.');
        });

    muteBtn.onclick = () => {
        if (!audioCtx) return;
        muted = !muted;
        if (muted) audioCtx.suspend(); else audioCtx.resume();
        muteBtn.textContent = muted ? 'Unmute' : 'Mute';
    };

    // Track Path (oval)
    const pathPoints = [];
    const segments = 720;
    const cx = width / 2, cy = height / 2;
    const rx = 200, ry = 120;
    for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        const x = cx + Math.cos(theta) * rx;
        const y = cy + Math.sin(theta) * ry;
        pathPoints.push({ x, y });
    }
    // Compute cumulative lengths
    const cumLen = [0];
    for (let i = 1; i < pathPoints.length; i++) {
        const dx = pathPoints[i].x - pathPoints[i - 1].x;
        const dy = pathPoints[i].y - pathPoints[i - 1].y;
        cumLen[i] = cumLen[i - 1] + Math.hypot(dx, dy);
    }
    const trackLength = cumLen[cumLen.length - 1];

    // Obstacles placed at fixed t values (0-1)
    const obstacleTs = [0.15, 0.4, 0.65, 0.9];
    const obstacles = obstacleTs.map(t => {
        const idx = Math.floor(t * (pathPoints.length - 1));
        return { t, pos: pathPoints[idx] };
    });

    // Car state
    const car = {
        t: 0, // 0-1 along track
        speed: 0, // pixel per second
        lap: 0,
        crashed: false,
        crashTimer: 0
    };
    const maxSpeedBase = 200; // max px/s at full volume
    const lapCountGoal = 3;
    let raceStarted = false;
    let raceStartTime = 0;
    let bestTime = localStorage.getItem('voiceRacingBest') ? Number(localStorage.getItem('voiceRacingBest')) : null;

    function getPosAt(t) {
        const total = t * (pathPoints.length - 1);
        const i = Math.floor(total);
        const frac = total - i;
        const p1 = pathPoints[i];
        const p2 = pathPoints[(i + 1) % pathPoints.length];
        const x = p1.x + (p2.x - p1.x) * frac;
        const y = p1.y + (p2.y - p1.y) * frac;
        return { x, y };
    }

    function getAngleAt(t) {
        const total = t * (pathPoints.length - 1);
        const i = Math.floor(total);
        const p1 = pathPoints[i];
        const p2 = pathPoints[(i + 1) % pathPoints.length];
        return Math.atan2(p2.y - p1.y, p2.x - p1.x);
    }

    function updateVolume() {
        if (!micReady) {
            volume = 0;
            return;
        }
        const data = new Uint8Array(analyser.frequencyBinCount);
        analyser.getByteFrequencyData(data);
        let sum = 0;
        for (let i = 0; i < data.length; i++) sum += data[i];
        volume = sum / (data.length * 255); // 0-1
    }

    function drawMeter() {
        meterCtx.clearRect(0, 0, meterCanvas.width, meterCanvas.height);
        meterCtx.fillStyle = '#333';
        meterCtx.fillRect(0, 0, meterCanvas.width, meterCanvas.height);
        meterCtx.fillStyle = '#0f0';
        meterCtx.fillRect(0, 0, volume * meterCanvas.width, meterCanvas.height);
        meterCtx.strokeStyle = '#fff';
        meterCtx.strokeRect(0, 0, meterCanvas.width, meterCanvas.height);
    }

    function drawTrack() {
        ctx.strokeStyle = '#777';
        ctx.lineWidth = 40;
        ctx.beginPath();
        for (let i = 0; i < pathPoints.length; i++) {
            const p = pathPoints[i];
            if (i === 0) ctx.moveTo(p.x, p.y);
            else ctx.lineTo(p.x, p.y);
        }
        ctx.closePath();
        ctx.stroke();

        // start/finish line
        const startIdx = 0;
        const pA = pathPoints[startIdx];
        const pB = pathPoints[(startIdx + 1) % pathPoints.length];
        const perp = Math.atan2(pB.y - pA.y, pB.x - pA.x) + Math.PI / 2;
        const lineLen = 40;
        const x1 = pA.x + Math.cos(perp) * lineLen / 2;
        const y1 = pA.y + Math.sin(perp) * lineLen / 2;
        const x2 = pA.x - Math.cos(perp) * lineLen / 2;
        const y2 = pA.y - Math.sin(perp) * lineLen / 2;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
    }

    function drawObstacles() {
        ctx.fillStyle = '#a00';
        obstacles.forEach(ob => {
            ctx.beginPath();
            ctx.arc(ob.pos.x, ob.pos.y, 12, 0, Math.PI * 2);
            ctx.fill();
        });
    }

    function drawCar() {
        const pos = getPosAt(car.t);
        const angle = getAngleAt(car.t);
        ctx.save();
        ctx.translate(pos.x, pos.y);
        ctx.rotate(angle);
        ctx.fillStyle = car.crashed ? '#f80' : '#0ff';
        ctx.beginPath();
        ctx.moveTo(12, 0);
        ctx.lineTo(-10, -8);
        ctx.lineTo(-10, 8);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
    }

    function checkCollision() {
        if (car.crashed) {
            car.crashTimer -= 1 / 60;
            if (car.crashTimer <= 0) car.crashed = false;
            return;
        }
        const carPos = getPosAt(car.t);
        obstacles.forEach(ob => {
            const dx = carPos.x - ob.pos.x;
            const dy = carPos.y - ob.pos.y;
            const dist = Math.hypot(dx, dy);
            if (dist < 20) {
                car.crashed = true;
                car.crashTimer = 1.0;
                car.speed *= 0.3; // lose speed
                // bounce back a bit
                car.t -= (car.speed / trackLength) * 0.2;
                if (car.t < 0) car.t += 1;
            }
        });
    }

    function update(dt) {
        if (!raceStarted) return;
        updateVolume();
        const targetSpeed = maxSpeedBase * volume;
        // simple acceleration smoothing
        const accel = 300;
        if (car.speed < targetSpeed) {
            car.speed = Math.min(car.speed + accel * dt, targetSpeed);
        } else {
            car.speed = Math.max(car.speed - accel * dt, targetSpeed);
        }
        if (!car.crashed) {
            car.t += (car.speed * dt) / trackLength;
            if (car.t >= 1) {
                car.t -= 1;
                car.lap += 1;
                // lap timing
                if (car.lap <= lapCountGoal) {
                    const now = performance.now();
                    const elapsed = (now - raceStartTime) / 1000;
                    timerDiv.textContent = `Lap ${car.lap}/${lapCountGoal} - ${elapsed.toFixed(2)}s`;
                    if (car.lap === lapCountGoal) {
                        raceStarted = false;
                        const totalTime = elapsed;
                        timerDiv.textContent = `Finished! Time: ${totalTime.toFixed(2)}s`;
                        if (!bestTime || totalTime < bestTime) {
                            bestTime = totalTime;
                            localStorage.setItem('voiceRacingBest', bestTime);
                            bestDiv.textContent = `New Best! ${bestTime.toFixed(2)}s`;
                        } else {
                            bestDiv.textContent = `Best: ${bestTime.toFixed(2)}s`;
                        }
                        celebrate();
                    }
                }
            }
        }
        checkCollision();
    }

    function celebrate() {
        let confetti = [];
        for (let i = 0; i < 100; i++) {
            confetti.push({
                x: cx,
                y: cy,
                vx: (Math.random() - 0.5) * 300,
                vy: (Math.random() - 0.5) * 300,
                size: Math.random() * 4 + 2,
                hue: Math.random() * 360
            });
        }
        const start = performance.now();
        function anim(t) {
            const dt = (t - start) / 1000;
            ctx.clearRect(0, 0, width, height);
            confetti.forEach(p => {
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                ctx.fillStyle = `hsl(${p.hue},80%,60%)`;
                ctx.fillRect(p.x, p.y, p.size, p.size);
            });
            if (dt < 3) requestAnimationFrame(anim);
            else drawScene();
        }
        requestAnimationFrame(anim);
    }

    function drawScene() {
        ctx.clearRect(0, 0, width, height);
        drawTrack();
        drawObstacles();
        drawCar();
    }

    function loop(timestamp) {
        const now = timestamp;
        const dt = (now - (loop.last || now)) / 1000;
        loop.last = now;
        update(dt);
        drawScene();
        drawMeter();
        requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);

    startBtn.onclick = () => {
        if (!micReady) return;
        raceStarted = true;
        car.t = 0;
        car.speed = 0;
        car.lap = 0;
        car.crashed = false;
        raceStartTime = performance.now();
        timerDiv.textContent = 'Lap 0/0';
        bestDiv.textContent = bestTime ? `Best: ${bestTime.toFixed(2)}s` : '';
    };
}

